/**
 * Algoritmo de sorteo para el amigo secreto.
 *
 * Genera una asignación aleatoria donde:
 * - Nadie se asigna a sí mismo (derangement).
 * - Todos regalan exactamente una vez y todos reciben exactamente una vez.
 */

export interface Participante {
  /** Nombre visible del participante. */
  nombre: string;
  /** Correo donde recibirá su asignación. */
  correo: string;
}

export interface Asignacion {
  /** Quién regala. */
  de: Participante;
  /** A quién le regala. */
  para: Participante;
}

/** Movimiento tipo Fisher-Yates: ordena el array en su lugar, uniformemente al azar. */
function mezclar<T>(items: T[]): T[] {
  for (let i = items.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [items[i], items[j]] = [items[j], items[i]];
  }
  return items;
}

/**
 * Sortea las asignaciones.
 *
 * Se mezcla aleatoriamente la lista de "receptores"; si la mezcla deja a
 * alguien emparejado consigo mismo (punto fijo), se re-mezcla completa.
 * Con 2 participantes la única posibilidad válida es que intercambien.
 * Devuelve null si no es posible (menos de 2 participantes).
 */
export function sortearAmigoSecreto(participantes: Participante[]): Asignacion[] | null {
  if (participantes.length < 2) {
    return null;
  }

  const maxIntentos = 1000;
  for (let intento = 0; intento < maxIntentos; intento++) {
    const receptores = mezclar([...participantes]);
    const hayPuntoFijo = participantes.some((p, i) => p === receptores[i]);
    if (hayPuntoFijo) continue;

    return participantes.map((de, i) => ({ de, para: receptores[i] }));
  }

  // Prácticamente inalcanzable: la probabilidad de fallar 1000 intentos es baja,
  // pero la caída ordenada (rotación circular) siempre es un derangement válido.
  const rotados = participantes.slice(1).concat(participantes[0]);
  return participantes.map((de, i) => ({ de, para: rotados[i] }));
}

import {
  createTransport,
  type SentMessageInfo,
  type Transporter,
} from "nodemailer";
import type { Asignacion } from "@/lib/sorteo";

let transporte: Transporter;

function obtenerTransporte(): Transporter {
  if (transporte) return transporte;

  const host = process.env.SMTP_HOST;
  const puerto = Number(process.env.SMTP_PORT ?? "587");

  if (!host) {
    throw new Error(
      "Falta la variable SMTP_HOST en la configuración (.env.local).",
    );
  }

  transporte = createTransport({
    host,
    port: puerto,
    // El puerto 465 usa TLS implícito; el resto negocia con STARTTLS.
    secure: puerto === 465,
    auth:
      process.env.SMTP_USER && process.env.SMTP_PASS
        ? { user: process.env.SMTP_USER, pass: process.env.SMTP_PASS }
        : undefined,
  });

  return transporte;
}

function remitente(): string {
  return process.env.SMTP_FROM ?? process.env.SMTP_USER ?? "amigo-secreto@localhost";
}

function construirCorreo(asignacion: Asignacion) {
  return {
    from: remitente(),
    to: asignacion.de.correo,
    subject: "🎁 Asignación de tu amigo secreto",
    text:
      `Hola ${asignacion.de.nombre}:\n\n` +
      `Ya se hizo el sorteo del amigo secreto 🎄\n\n` +
      `Te toca regalar a: ${asignacion.para.nombre}\n\n` +
      `Recuerda mantener en secreto tu asignación. ¡Felices fiestas!`,
    html:
      `<p>Hola <strong>${asignacion.de.nombre}</strong>:</p>` +
      `<p>Ya se hizo el sorteo del amigo secreto 🎄</p>` +
      `<p>Te toca regalar a: <strong>${asignacion.para.nombre}</strong></p>` +
      `<p>Recuerda mantener en secreto tu asignación. ¡Felices fiestas!</p>`,
  };
}

/**
 * Envía un correo por cada asignación, de forma secuencial.
 * Solo expone el nombre del destinatario dentro de su propio correo.
 * Lanza una excepción si algún correo no se pudo enviar (sin reintentos).
 */
export async function enviarAsignaciones(asignaciones: Asignacion[]): Promise<number> {
  const cliente = obtenerTransporte();
  let enviados = 0;

  for (const asignacion of asignaciones) {
    await cliente.sendMail(construirCorreo(asignacion));
    enviados++;
  }

  return enviados;
}

import { enviaCorreo } from "@/lib/sorteo";

export const runtime = "nodejs"; // nodemailer requiere runtime de Node

export async function POST(request: Request) {
  const resultado = validarSolicitud(await request.json());

  if ("error" in resultado) {
    return Response.json({ error: resultado.error }, { status: 400 });
  }

  const asignaciones = sortearAmigoSecreto(resultado.participantes);
  if (!asignaciones) {
    return Response.json(
      { error: "Se requieren al menos 2 participantes para el sorteo." },
      { status: 400 },
    );
  }

  return Response.json({ ok: true, enviados: asignaciones.length });
}

import { sortearAmigoSecreto, type Participante } from "@/lib/sorteo";
import { enviarAsignaciones } from "@/lib/mailer";

export const runtime = "nodejs"; // nodemailer requiere runtime de Node

/** Regex de formato simple, suficiente para validar al ingreso. */
const REGEX_CORREO = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

type ResultadoValidacion =
  | { participantes: Participante[] }
  | { error: string };

function validarSolicitud(cuerpo: unknown): ResultadoValidacion {
  if (cuerpo === null || typeof cuerpo !== "object") {
    return { error: "Cuerpo de solicitud inválido." };
  }

  const { participantes } = cuerpo as { participantes?: unknown };
  if (!Array.isArray(participantes)) {
    return { error: "La lista de participantes es inválida." };
  }

  const limpios: Participante[] = [];
  const correosVistos = new Set<string>();

  for (const crudo of participantes) {
    if (crudo === null || typeof crudo !== "object") {
      return { error: "Hay un participante con datos inválidos." };
    }

    const nombre = String((crudo as { nombre?: unknown }).nombre ?? "").trim();
    const correo = String((crudo as { correo?: unknown }).correo ?? "").trim();

    if (nombre.length === 0) {
      return { error: "Todos los participantes deben tener un nombre." };
    }
    if (!REGEX_CORREO.test(correo)) {
      return { error: `El correo "${correo || "(vacío)"}" no es válido.` };
    }
    if (correosVistos.has(correo.toLowerCase())) {
      return { error: `El correo ${correo} está repetido.` };
    }

    correosVistos.add(correo.toLowerCase());
    limpios.push({ nombre, correo });
  }

  return { participantes: limpios };
}

export async function POST(request: Request) {
  let cuerpo: unknown;
  try {
    cuerpo = await request.json();
  } catch {
    return Response.json({ error: "El cuerpo no es JSON válido." }, { status: 400 });
  }

  const resultado = validarSolicitud(cuerpo);
  if ("error" in resultado) {
    return Response.json({ error: resultado.error }, { status: 400 });
  }

  const asignaciones = sortearAmigoSecreto(resultado.participantes);
  if (!asignaciones) {
    return Response.json(
      { error: "Se requieren al menos 2 participantes para el sorteo." },
      { status: 400 },
    );
  }

  try {
    const enviados = await enviarAsignaciones(asignaciones);
    return Response.json({ ok: true, enviados });
  } catch (error) {
    console.error("Fallo al enviar correos del sorteo:", error);
    return Response.json(
      {
        error:
          "El sorteo se realizó pero falló el envío de correos. " +
          "Revisa la configuración SMTP y vuelve a realizar el sorteo.",
      },
      { status: 502 },
    );
  }
}

"use client";

import { useState } from "react";

const REGEX_CORREO = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export interface Participante {
  nombre: string;
  correo: string;
}

interface Props {
  alAgregar: (participante: Participante) => string | null;
}

/** Formulario de alta de participante (nombre + correo) con validación en vivo. */
export default function ParticipantForm({ alAgregar }: Props) {
  const [nombre, setNombre] = useState("");
  const [correo, setCorreo] = useState("");
  const [error, setError] = useState<string | null>(null);

  const nombreValido = nombre.trim().length > 0;
  const correoValido = REGEX_CORREO.test(correo.trim());

  function manejarEnvio(e: React.FormEvent) {
    e.preventDefault();
    if (!nombreValido) {
      setError("Ingresa el nombre del participante.");
      return;
    }
    if (!correoValido) {
      setError("Ingresa un correo válido.");
      return;
    }

    const problema = alAgregar({ nombre: nombre.trim(), correo: correo.trim() });
    if (problema) {
      setError(problema);
      return;
    }

    setNombre("");
    setCorreo("");
    setError(null);
  }

  return (
    <form onSubmit={manejarEnvio} className="space-y-2" noValidate>
      <div className="grid gap-2 sm:grid-cols-[1fr_1fr_auto]">
        <input
          type="text"
          placeholder="Nombre"
          value={nombre}
          onChange={(e) => {
            setNombre(e.target.value);
            setError(null);
          }}
          autoComplete="off"
          className="rounded-md border border-zinc-300 px-3 py-2 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200"
          aria-label="Nombre del participante"
        />
        <input
          type="email"
          placeholder="correo@ejemplo.com"
          value={correo}
          onChange={(e) => {
            setCorreo(e.target.value);
            setError(null);
          }}
          autoComplete="off"
          className="rounded-md border border-zinc-300 px-3 py-2 text-sm outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200"
          aria-label="Correo del participante"
        />
        <button
          type="submit"
          className="rounded-md bg-indigo-600 px-4 py-2 text-sm font-medium text-white transition hover:bg-indigo-700 active:bg-indigo-800"
        >
          Agregar
        </button>
      </div>
      <p aria-live="polite" className="min-h-5 text-sm text-red-600">
        {error}
      </p>
    </form>
  );
}

"use client";

import type { Participante } from "@/components/ParticipantForm";

interface Props {
  participantes: Participante[];
  alEliminar: (indice: number) => void;
}

/** Tabla de participantes registrados, cada uno eliminable. */
export default function ParticipantTable({ participantes, alEliminar }: Props) {
  if (participantes.length === 0) {
    return (
      <p className="text-sm text-zinc-500">
        Aún no hay participantes. Agrega al menos 2 para poder sortear.
      </p>
    );
  }

  return (
    <div className="overflow-x-auto">
      <table className="w-full text-sm">
        <thead>
          <tr className="border-b border-zinc-200 text-left text-xs uppercase tracking-wide text-zinc-500">
            <th className="py-2 pr-4">#</th>
            <th className="py-2 pr-4">Nombre</th>
            <th className="py-2 pr-4">Correo</th>
            <th className="py-2" aria-label="Acciones" />
          </tr>
        </thead>
        <tbody>
          {participantes.map((p, indice) => (
            <tr key={`${p.correo}-${indice}`} className="border-b border-zinc-100">
              <td className="py-2 pr-4 text-zinc-400">{indice + 1}</td>
              <td className="py-2 pr-4 font-medium">{p.nombre}</td>
              <td className="py-2 pr-4 text-zinc-600">{p.correo}</td>
              <td className="py-2 text-right">
                <button
                  type="button"
                  onClick={() => alEliminar(indice)}
                  className="rounded px-2 py-1 text-xs text-red-600 transition hover:bg-red-50"
                  aria-label={`Eliminar a ${p.nombre}`}
                >
                  Eliminar
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <p className="mt-2 text-xs text-zinc-400">
        {participantes.length} participante{participantes.length !== 1 && "s"}
      </p>
    </div>
  );
}

"use client";

interface Props {
  deshabilitado: boolean;
  cargando: boolean;
  alLanzar: () => void;
}

/** Botón que dispara el sorteo y el envío de correos. */
export default function SorteoButton({ deshabilitado, cargando, alLanzar }: Props) {
  return (
    <button
      type="button"
      onClick={alLanzar}
      disabled={deshabilitado || cargando}
      className="rounded-md bg-emerald-600 px-6 py-2.5 text-sm font-semibold text-white shadow transition enabled:hover:bg-emerald-700 enabled:active:bg-emerald-800 disabled:cursor-not-allowed disabled:bg-zinc-300"
    >
      {cargando ? "Sorteando y enviando correos…" : "🎁 Realizar sorteo"}
    </button>
  );
}

"use client";

import { useState } from "react";
import ParticipantForm, {
  type Participante,
} from "@/components/ParticipantForm";
import ParticipantTable from "@/components/ParticipantTable";
import SorteoButton from "@/components/SorteoButton";

type EstadoMensaje =
  | { tipo: "exito"; texto: string }
  | { tipo: "error"; texto: string }
  | null;

/** Orquesta el flujo completo: agregar participantes → sortear → enviar correos. */
export default function SorteoApp() {
  const [participantes, setParticipantes] = useState<Participante[]>([]);
  const [cargando, setCargando] = useState(false);
  const [mensaje, setMensaje] = useState<EstadoMensaje>(null);

  function agregar(p: Participante): string | null {
    const duplicado = participantes.some(
      (x) => x.correo.toLowerCase() === p.correo.toLowerCase(),
    );
    if (duplicado) {
      return "Ese correo ya está registrado.";
    }
    setParticipantes((prev) => [...prev, p]);
    setMensaje(null);
    return null;
  }

  function eliminar(indice: number) {
    setParticipantes((prev) => prev.filter((_, i) => i !== indice));
    setMensaje(null);
  }

  async function lanzarSorteo() {
    setCargando(true);
    setMensaje(null);
    try {
      const respuesta = await fetch("/api/sorteo", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ participantes }),
      });
      const cuerpo = await respuesta.json();

      if (!respuesta.ok) {
        setMensaje({
          tipo: "error",
          texto: cuerpo.error ?? "Ocurrió un error inesperado.",
        });
      } else {
        setMensaje({
          tipo: "exito",
          texto: `¡Sorteo realizado! Se enviaron ${cuerpo.enviados} correos con las asignaciones.`,
        });
        setParticipantes([]);
      }
    } catch {
      setMensaje({
        tipo: "error",
        texto: "No se pudo contactar al servidor. Vuelve a intentarlo.",
      });
    } finally {
      setCargando(false);
    }
  }

  const puedeSortear = participantes.length >= 2 && !cargando;

  return (
    <div className="space-y-8">
      <section className="rounded-xl border border-zinc-200 bg-white p-6 shadow-sm">
        <h2 className="mb-4 text-lg font-semibold">1. Agrega participantes</h2>
        <ParticipantForm alAgregar={agregar} />
      </section>

      <section className="rounded-xl border border-zinc-200 bg-white p-6 shadow-sm">
        <h2 className="mb-4 text-lg font-semibold">2. Lista de participantes</h2>
        <ParticipantTable participantes={participantes} alEliminar={eliminar} />
      </section>

      <section className="rounded-xl border border-zinc-200 bg-white p-6 shadow-sm">
        <h2 className="mb-4 text-lg font-semibold">3. Sorteo</h2>
        <div className="flex flex-wrap items-center gap-4">
          <SorteoButton
            deshabilitado={participantes.length < 2}
            cargando={cargando}
            alLanzar={lanzarSorteo}
          />
          {participantes.length < 2 && (
            <span className="text-sm text-zinc-500">
              Se necesitan al menos 2 participantes para sortear.
            </span>
          )}
        </div>
        <p className="mt-3 text-sm text-zinc-500">
          Nadie recibirá su propio nombre y cada persona regalará y recibirá exactamente una vez. Cada participante recibirá su asignación por correo, y cada correo mostrará únicamente a quién le toca regalar.
        </p>
        {mensaje && (
          <p
            aria-live="polite"
            className={
              mensaje.tipo === "exito"
                ? "mt-4 rounded-md bg-emerald-50 px-4 py-2 text-sm text-emerald-700"
                : "mt-4 rounded-md bg-red-50 px-4 py-2 text-sm text-red-700"
            }
          >
            {mensaje.texto}
          </p>
        )}
      </section>
    </div>
  );
}

import SorteoApp from "@/components/SorteoApp";

export default function Home() {
  return (
    <main className="mx-auto w-full max-w-2xl flex-1 px-4 py-10">
      <header className="mb-8 text-center">
        <h1 className="text-3xl font-bold tracking-tight">🎅 Amigo Secreto</h1>
        <p className="mt-2 text-zinc-600">
          Registra a los participantes, haz el sorteo y recibe cada asignación
          por correo.
        </p>
      </header>
      <SorteoApp />
    </main>
  );
}

import type { Metadata } from "next";
import "./globals.css";

export const metadata: Metadata = {
  title: "Amigo Secreto",
  description:
    "Organiza un sorteo de amigo secreto: registra participantes, haz el sorteo y envía las asignaciones por correo.",
};

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html lang="es" className="h-full antialiased">
      <body className="flex min-h-full flex-col bg-zinc-100 font-sans">
        {children}
      </body>
    </html>
  );
}

