// Servidor SMTP falso para pruebas: registra DATA en /tmp/opencode/smtp-mails.log
import net from "node:net";

const fs = require("node:fs");

const server = net.createServer((socket) => {
  socket.write("220 dummy ESMTP\r\n");
  let buffer = "";
  let enData = false;

  socket.on("data", (chunk) => {
    const texto = chunk.toString();
    if (enData) {
      buffer += texto;
      if (/\r\n\.\r\n/.test(buffer)) {
        fs.appendFileSync("/tmp/opencode/smtp-mails.log", buffer + "\n=====\n");
        buffer = "";
        enData = false;
        socket.write("250 OK\r\n");
      }
      return;
    }
    buffer = texto.trim().toUpperCase();
    if (buffer === "DATA") {
      enData = true;
      buffer = "";
      socket.write("354 End data with <CR><LF>.<CR><LF>\r\n");
    } else if (buffer === "QUIT") {
      socket.write("221 Bye\r\n");
      socket.end();
    } else {
      socket.write("250 OK\r\n");
    }
  });
});

server.listen(2525, () => console.log("SMTP falso en 2525"));

// Servidor SMTP falso para pruebas: registra DATA en /tmp/opencode/smtp-mails.log
const net = require("node:net");
const fs = require("node:fs");

const server = net.createServer((socket) => {
  socket.write("220 dummy ESMTP\r\n");
  let dataBuffer = "";
  let enData = false;

  socket.on("data", (chunk) => {
    if (enData) {
      dataBuffer += chunk.toString();
      if (/\r\n\.\r\n/.test(dataBuffer) || /\n\.\n/.test(dataBuffer)) {
        fs.appendFileSync("/tmp/opencode/smtp-mails.log", dataBuffer + "\n=====\n");
        dataBuffer = "";
        enData = false;
        socket.write("250 OK\r\n");
      }
      return;
    }
    const linea = chunk.toString().trim().toUpperCase();
    if (linea === "DATA") {
      enData = true;
      dataBuffer = "";
      socket.write("354 End data with <CR><LF>.<CR><LF>\r\n");
    } else if (linea === "QUIT") {
      socket.write("221 Bye\r\n");
      socket.end();
    } else {
      socket.write("250 OK\r\n");
    }
  });
});

server.listen(2525, () => console.log("SMTP falso en 2525"));
